examples.code:
DROP TABLE IF EXISTS order_items;
CREATE TABLE order_items (item_id INTEGER PRIMARY KEY, quantity INTEGER, unit_price REAL);
INSERT INTO order_items VALUES (1,3,120.0),(2,2,75.0);
SELECT item_id,quantity*unit_price AS line_total,quantity*unit_price-50 AS after_discount FROM order_items ORDER BY item_id;

DROP TABLE IF EXISTS applicants;
CREATE TABLE applicants (applicant_id INTEGER PRIMARY KEY, age INTEGER, score INTEGER);
INSERT INTO applicants VALUES (1,22,80),(2,17,95),(3,30,65);
SELECT applicant_id FROM applicants WHERE age>=18 AND score<>65 ORDER BY applicant_id;

DROP TABLE IF EXISTS tickets;
CREATE TABLE tickets (ticket_id INTEGER PRIMARY KEY, priority TEXT, status TEXT);
INSERT INTO tickets VALUES (1,'High','Open'),(2,'Low','Open'),(3,'High','Closed'),(4,'Medium','Open');
SELECT ticket_id FROM tickets WHERE (priority='High' OR priority='Medium') AND status='Open' ORDER BY ticket_id;

DROP TABLE IF EXISTS people;
CREATE TABLE people (first_name TEXT, last_name TEXT);
INSERT INTO people VALUES ('Asha','Rao'),('Bilal','Khan');
SELECT first_name || ' ' || last_name AS full_name FROM people ORDER BY last_name;

DROP TABLE IF EXISTS numbers;
CREATE TABLE numbers (value INTEGER);
INSERT INTO numbers VALUES (2),(5),(8),(11);
SELECT value FROM numbers WHERE value BETWEEN 2 AND 10 AND value%2=0 ORDER BY value;

